<script setup>
import {computed,onMounted,ref,watch} from 'vue'
import {api} from './api'
const props=defineProps({channel:{type:String,default:'telegram'}})
const campaigns=ref([]),accounts=ref([]),selected=ref(null),loading=ref(false),saving=ref(false),error=ref(''),success=ref('')
const campaignOpen=ref(false),stepOpen=ref(false),editingStep=ref(null),builder=ref(false),builderStage=ref(1)
const form=ref({name:'',description:'',channel_account_id:'',audience_type:'all',scheduled_at:''})
const step=ref({name:'',delay_seconds:0,message_mode:'freeform',message_text:'',parse_mode:'HTML',media_url:'',media_type:'image'})
const channelLabel=computed(()=>props.channel==='telegram'?'Telegram':'WhatsApp')
const activeAccounts=computed(()=>(accounts.value||[]).filter(x=>x.active))
function fmt(v){return v?new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'—'}
function accountName(a){return props.channel==='telegram'?(a.name||a.username||('Bot '+a.id)):(a.verified_name||a.display_phone_number||('WhatsApp '+a.id))}
function delayLabel(n){n=Number(n||0);if(!n)return 'Immediately';if(n%86400===0)return (n/86400)+' day'+(n===86400?'':'s')+' later';if(n%3600===0)return (n/3600)+' hour'+(n===3600?'':'s')+' later';if(n%60===0)return (n/60)+' minute'+(n===60?'':'s')+' later';return n+' seconds later'}
async function load(){loading.value=true;error.value='';try{accounts.value=props.channel==='telegram'?await api.telegramBots():await api.whatsappConnections();campaigns.value=await api.messagingCampaigns(props.channel);if(selected.value){const found=campaigns.value.find(x=>x.id===selected.value.id);selected.value=found?await api.messagingCampaign(found.id):null}}catch(e){error.value=e.message}finally{loading.value=false}}
function newCampaign(){form.value={name:'',description:'',channel_account_id:activeAccounts.value[0]?.id||'',audience_type:'all',scheduled_at:''};selected.value=null;builderStage.value=1;builder.value=true}
async function saveCampaign(){if(!form.value.name.trim()||!form.value.channel_account_id)return;saving.value=true;error.value='';try{const c=await api.createMessagingCampaign({name:form.value.name.trim(),description:form.value.description||null,channel:props.channel,channel_account_id:Number(form.value.channel_account_id),audience_type:form.value.audience_type,scheduled_at:form.value.scheduled_at||null});campaignOpen.value=false;success.value='Campaign draft created.';await load();selected.value=await api.messagingCampaign(c.id);builderStage.value=2}catch(e){error.value=e.message}finally{saving.value=false}}
async function openCampaign(c){selected.value=await api.messagingCampaign(c.id);form.value={name:selected.value.name||'',description:selected.value.description||'',channel_account_id:selected.value.channel_account_id||'',audience_type:selected.value.audience_type||'all',scheduled_at:selected.value.scheduled_at||''};builderStage.value=2;builder.value=true}
function newStep(){editingStep.value=null;step.value={name:'Message '+((selected.value?.steps?.length||0)+1),delay_seconds:0,message_mode:'freeform',message_text:'',parse_mode:'HTML',media_url:'',media_type:'image'};stepOpen.value=true}
function editStep(s){editingStep.value=s.id;step.value={name:s.name,delay_seconds:s.delay_seconds,message_mode:s.message_mode,message_text:s.message_text,parse_mode:s.parse_mode||'HTML',media_url:s.media_url||'',media_type:s.media_type||'image'};stepOpen.value=true}
async function saveStep(){if(!selected.value||!step.value.name.trim()||!step.value.message_text.trim())return;saving.value=true;error.value='';try{const payload={...step.value,name:step.value.name.trim(),delay_seconds:Number(step.value.delay_seconds||0),media_url:step.value.media_url||null,media_type:step.value.media_url?step.value.media_type:null};if(editingStep.value)await api.updateMessagingCampaignStep(selected.value.id,editingStep.value,payload);else await api.addMessagingCampaignStep(selected.value.id,payload);selected.value=await api.messagingCampaign(selected.value.id);campaigns.value=await api.messagingCampaigns(props.channel);stepOpen.value=false;success.value='Campaign step saved.'}catch(e){error.value=e.message}finally{saving.value=false}}
async function removeStep(s){if(!confirm('Delete “'+s.name+'” from this campaign?'))return;try{await api.deleteMessagingCampaignStep(selected.value.id,s.id);selected.value=await api.messagingCampaign(selected.value.id);await load()}catch(e){error.value=e.message}}
async function moveStep(s,direction){try{await api.moveMessagingCampaignStep(selected.value.id,s.id,direction);selected.value=await api.messagingCampaign(selected.value.id);await load()}catch(e){error.value=e.message}}
async function removeCampaign(c){if(!confirm('Delete campaign “'+c.name+'”?'))return;try{await api.deleteMessagingCampaign(c.id);if(selected.value?.id===c.id)selected.value=null;await load();success.value='Campaign deleted.'}catch(e){error.value=e.message}}
async function runtimeAction(action,campaign=selected.value){if(!campaign)return;error.value='';success.value='';try{if(action==='launch'){if(!confirm('Launch “'+campaign.name+'” to its snapshotted audience?'))return;await api.launchMessagingCampaign(campaign.id);success.value='Campaign launched.'}else if(action==='pause'){await api.pauseMessagingCampaign(campaign.id);success.value='Campaign paused.'}else if(action==='resume'){await api.resumeMessagingCampaign(campaign.id);success.value='Campaign resumed.'}else if(action==='cancel'){if(!confirm('Cancel “'+campaign.name+'”? Pending messages will not be sent.'))return;await api.cancelMessagingCampaign(campaign.id);success.value='Campaign cancelled.'}await load();if(builder.value&&campaign.id)selected.value=await api.messagingCampaign(campaign.id)}catch(e){error.value=e.message}}
watch(()=>props.channel,()=>{selected.value=null;campaignOpen.value=false;stepOpen.value=false;builder.value=false;load()})
onMounted(load)
</script>
<template>
<section class="campaign-engine">
  <template v-if="!builder">
    <div class="toolbar"><div><strong>Campaign workspace</strong><span>{{campaigns.length}} campaign{{campaigns.length===1?'':'s'}}</span></div><button class="primary" @click="newCampaign">+ New Campaign</button></div>
    <p v-if="error" class="notice error">{{error}}</p><p v-if="success" class="notice success">{{success}}</p>
    <div class="card">
      <div v-if="loading" class="empty">Loading campaigns…</div>
      <div v-else-if="!campaigns.length" class="empty"><strong>No {{channelLabel}} campaigns yet.</strong><p>Create a campaign, then add the messages that should run in sequence.</p></div>
      <div v-for="c in campaigns" :key="c.id" class="row" @click="openCampaign(c)"><div class="title"><strong>{{c.name}}</strong><small>{{c.description||'No description'}} · {{c.step_count}} step{{c.step_count===1?'':'s'}}</small></div><span class="pill">{{c.status}}</span><span>{{fmt(c.updated_at)}}</span><div class="row-actions"><button v-if="c.status==='draft' && c.step_count" class="primary compact" @click.stop="runtimeAction('launch',c)">Launch</button><button v-if="c.status==='running'||c.status==='scheduled'" @click.stop="runtimeAction('pause',c)">Pause</button><button v-if="c.status==='paused'" @click.stop="runtimeAction('resume',c)">Resume</button><button v-if="['running','scheduled','paused'].includes(c.status)" class="danger" @click.stop="runtimeAction('cancel',c)">Cancel</button><button v-if="c.status==='draft'" class="danger" @click.stop="removeCampaign(c)">Delete</button></div><button class="chev">›</button></div>
    </div>
  </template>

  <template v-else>
    <div class="builder-top"><button class="back" @click="builder=false">← Campaigns</button><div><small>{{selected?'EDIT CAMPAIGN':'NEW '+channelLabel.toUpperCase()+' CAMPAIGN'}}</small><h2>{{selected?.name||'Create campaign'}}</h2></div></div>
    <div class="stagebar"><button :class="{active:builderStage===1,done:builderStage>1}" @click="builderStage=1"><b>1</b> Campaign details</button><button :disabled="!selected" :class="{active:builderStage===2}" @click="builderStage=2"><b>2</b> Message sequence</button><button :disabled="!selected" :class="{active:builderStage===3}" @click="builderStage=3"><b>3</b> Timing & review</button></div>
    <p v-if="error" class="notice error">{{error}}</p><p v-if="success" class="notice success">{{success}}</p>

    <div v-if="builderStage===1" class="builder-card">
      <div class="section-head"><div><h3>Campaign details</h3><p>Choose the channel account and audience for this campaign.</p></div></div>
      <label>Campaign name<input v-model="form.name" placeholder="e.g. September re-engagement"></label>
      <label>Description<textarea v-model="form.description" rows="3" placeholder="Optional internal description"></textarea></label>
      <div class="grid2"><label>{{channelLabel}} account<select v-model="form.channel_account_id"><option value="" disabled>Select account…</option><option v-for="a in activeAccounts" :key="a.id" :value="a.id">{{accountName(a)}}</option></select></label><label>Audience<select v-model="form.audience_type"><option value="all">All eligible contacts</option><option value="filtered">Filtered audience</option></select></label></div>
      <div class="actions"><button @click="builder=false">Cancel</button><button class="primary" :disabled="saving||!form.name.trim()||!form.channel_account_id" @click="saveCampaign">{{saving?'Saving…':'Save & continue →'}}</button></div>
    </div>

    <div v-else-if="builderStage===2 && selected" class="builder-card">
      <div class="section-head"><div><h3>Message sequence</h3><p>Messages run from top to bottom. Each delay is measured from the previous step.</p></div><button class="primary" @click="newStep">+ Add message</button></div>
      <div v-if="!selected.steps?.length" class="empty inner">No messages yet. Add the first message to start building this campaign.</div>
      <div v-for="(s,i) in selected.steps" :key="s.id" class="step-card">
        <div class="step-num">{{i+1}}</div><div class="step-main"><div class="step-head"><strong>{{s.name}}</strong><span>{{delayLabel(s.delay_seconds)}}</span></div><div class="message">{{s.message_text}}</div><small v-if="s.media_url">{{s.media_type}} · {{s.media_url}}</small></div>
        <div class="step-actions"><button :disabled="i===0" @click="moveStep(s,'up')">↑</button><button :disabled="i===selected.steps.length-1" @click="moveStep(s,'down')">↓</button><button @click="editStep(s)">Edit</button><button class="danger" @click="removeStep(s)">Delete</button></div>
      </div>
      <div class="actions"><button @click="builderStage=1">← Details</button><button class="primary" :disabled="!selected.steps?.length" @click="builderStage=3">Timing & review →</button></div>
    </div>

    <div v-else-if="builderStage===3 && selected" class="builder-card">
      <div class="section-head"><div><h3>Timing & review</h3><p>Review the campaign sequence before we connect launch and recipient runtime.</p></div></div>
      <div class="review-grid"><div><small>CHANNEL</small><strong>{{channelLabel}}</strong></div><div><small>AUDIENCE</small><strong>{{selected.audience_type==='all'?'All eligible contacts':'Filtered audience'}}</strong></div><div><small>MESSAGES</small><strong>{{selected.steps?.length||0}}</strong></div><div><small>STATUS</small><strong>{{selected.status}}</strong></div></div>
      <div class="timeline"><div v-for="(s,i) in selected.steps" :key="s.id" class="timeline-row"><b>{{i+1}}</b><div><strong>{{s.name}}</strong><small>{{delayLabel(s.delay_seconds)}}</small><p>{{s.message_text}}</p></div></div></div>
      <div class="runtime-note"><strong>Runtime ready.</strong><span>Launching snapshots the Telegram audience. Each recipient then advances independently through this sequence using the delay after the previous successful message.</span></div>
      <div class="actions"><button @click="builderStage=2">← Sequence</button><button @click="builder=false">Save draft</button><button v-if="selected.status==='draft'" class="primary" @click="runtimeAction('launch')">Launch campaign</button><button v-if="selected.status==='running'||selected.status==='scheduled'" @click="runtimeAction('pause')">Pause</button><button v-if="selected.status==='paused'" class="primary" @click="runtimeAction('resume')">Resume</button><button v-if="['running','scheduled','paused'].includes(selected.status)" class="danger" @click="runtimeAction('cancel')">Cancel</button></div>
    </div>
  </template>

  <div v-if="stepOpen" class="overlay" @click.self="stepOpen=false"><div class="modal"><div class="modal-head"><div><small>CAMPAIGN MESSAGE</small><h2>{{editingStep?'Edit':'Add'}} message</h2></div><button @click="stepOpen=false">×</button></div><label>Step name<input v-model="step.name"></label><label>Delay after previous step<select v-model.number="step.delay_seconds"><option :value="0">Immediately</option><option :value="300">5 minutes</option><option :value="3600">1 hour</option><option :value="21600">6 hours</option><option :value="86400">1 day</option><option :value="172800">2 days</option><option :value="604800">7 days</option></select></label><label>Message<textarea v-model="step.message_text" rows="7" placeholder="Enter the message…"></textarea></label><div class="grid2"><label>Media URL<input v-model="step.media_url" placeholder="Optional"></label><label>Media type<select v-model="step.media_type"><option value="image">Image</option><option value="video">Video</option><option value="document">Document</option></select></label></div><p class="hint">Variables and provider-specific template controls will use the same field/template infrastructure as Broadcasts when campaign delivery is connected.</p><div class="actions"><button @click="stepOpen=false">Cancel</button><button class="primary" :disabled="saving||!step.name.trim()||!step.message_text.trim()" @click="saveStep">{{saving?'Saving…':'Save message'}}</button></div></div></div>
</section>
</template>
<style scoped>
.builder-top{display:flex;gap:16px;align-items:center;margin-bottom:18px}.builder-top h2{margin:2px 0}.builder-top small{color:#07804a;font-weight:800}.back{border:1px solid #d5ded9;background:#fff;border-radius:8px;padding:9px 12px;cursor:pointer}.stagebar{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:18px}.stagebar button{display:flex;align-items:center;gap:9px;padding:12px;border:1px solid #d8e1dd;background:#fff;color:#697870;border-radius:9px;text-align:left;font-weight:700}.stagebar button b{width:25px;height:25px;border-radius:50%;background:#eef2f0;display:grid;place-items:center}.stagebar button.active{border-color:#15945a;color:#15382a;background:#f4fbf7}.stagebar button.active b,.stagebar button.done b{background:#16ad65;color:#fff}.stagebar button:disabled{opacity:.45}.builder-card{background:#fff;border:1px solid #dce4e0;border-radius:14px;padding:22px;max-width:1050px}.builder-card>label,.builder-card .grid2>label{display:flex;flex-direction:column;gap:6px;font-weight:700;font-size:13px;margin:12px 0}.builder-card input,.builder-card textarea,.builder-card select{border:1px solid #cfd9d4;border-radius:8px;padding:10px;font:inherit;background:#fff}.section-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:14px}.section-head h3{margin:0}.section-head p{margin:4px 0;color:#74837c}.review-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:16px 0}.review-grid>div{padding:14px;border:1px solid #e0e7e3;border-radius:9px;display:flex;flex-direction:column}.review-grid small{color:#74837c;font-weight:800}.timeline{margin:18px 0}.timeline-row{display:flex;gap:12px;padding:13px 0;border-bottom:1px solid #e5ebe8}.timeline-row>b{width:28px;height:28px;border-radius:50%;background:#e7f5ed;color:#087743;display:grid;place-items:center}.timeline-row>div{display:flex;flex-direction:column}.timeline-row small{color:#74837c}.timeline-row p{margin:6px 0;white-space:pre-wrap}.runtime-note{display:flex;gap:8px;padding:12px;background:#f0f7f3;border-radius:8px;color:#496057;font-size:13px}.campaign-engine{margin:0 -38px;padding:8px 38px 60px}.toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.toolbar>div{display:flex;gap:12px;align-items:baseline}.toolbar span{color:#728078;font-size:13px}.primary{background:#111a2d;color:#fff;border:0;border-radius:7px;padding:10px 14px;font-weight:750;cursor:pointer}.card{background:#fff;border:1px solid #dce4e0;border-radius:14px;overflow:hidden}.row{display:grid;grid-template-columns:minmax(280px,1fr) 90px 180px auto 28px;align-items:center;gap:12px;padding:15px 18px;border-bottom:1px solid #e5ebe8;cursor:pointer}.title{display:flex;flex-direction:column}.title small{color:#708078;margin-top:3px}.pill{justify-self:start;background:#f0f3f2;border-radius:999px;padding:4px 9px;font-size:11px;font-weight:800;text-transform:capitalize}.danger{color:#c72c25;border:1px solid #efbbb7;background:#fff}.row button,.step-actions button,.actions button,.modal-head button{border-radius:7px;padding:7px 10px;border:1px solid #d5ded9;background:#fff;cursor:pointer}.row-actions{display:flex;gap:6px;justify-content:flex-end}.row-actions button{white-space:nowrap}.compact{padding:7px 10px!important}.chev{border:0!important}.detail{padding:18px 22px 24px;background:#fbfcfc;border-bottom:1px solid #dfe7e3}.detail-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:14px}.detail-head h3{margin:0}.detail-head p{margin:4px 0;color:#74837c;font-size:13px}.step-card{display:flex;gap:14px;align-items:flex-start;padding:14px;background:#fff;border:1px solid #dfe7e3;border-radius:10px;margin:9px 0}.step-num{width:30px;height:30px;border-radius:50%;background:#e7f5ed;color:#087743;display:grid;place-items:center;font-weight:800}.step-main{flex:1}.step-head{display:flex;gap:12px;align-items:center}.step-head span{font-size:12px;color:#73827a;background:#f2f5f3;padding:3px 7px;border-radius:999px}.message{white-space:pre-wrap;margin-top:8px}.step-main small{display:block;color:#74837c;margin-top:8px}.step-actions{display:flex;gap:5px}.step-actions button:disabled{opacity:.35}.foundation-note{display:flex;gap:8px;margin-top:16px;padding:12px;background:#f0f7f3;border-radius:8px;color:#496057;font-size:13px}.empty{padding:42px;text-align:center;color:#728078}.empty strong{color:#203128}.empty p{margin:6px 0}.empty.inner{padding:24px}.notice{margin:0 0 12px}.notice.error{color:#bd2922}.notice.success{color:#087b47}.overlay{position:fixed;inset:0;background:rgba(20,28,35,.52);display:grid;place-items:center;z-index:1000;padding:24px}.modal{width:min(620px,100%);max-height:90vh;overflow:auto;background:#fff;border-radius:14px;padding:20px;box-shadow:0 20px 60px rgba(0,0,0,.2)}.modal-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:16px}.modal-head small{color:#07804a;font-weight:800}.modal-head h2{margin:3px 0}.modal-head button{font-size:22px;border:0}.modal label{display:flex;flex-direction:column;gap:6px;font-weight:700;font-size:13px;margin:12px 0}.modal input,.modal textarea,.modal select{border:1px solid #cfd9d4;border-radius:8px;padding:10px;font:inherit;background:#fff}.grid2{display:grid;grid-template-columns:1fr 180px;gap:10px}.hint{font-size:12px;color:#718078;background:#f5f7f6;padding:10px;border-radius:7px}.actions{display:flex;justify-content:flex-end;gap:8px;margin-top:18px}.actions .primary{background:#111a2d;color:#fff}.actions button:disabled{opacity:.5}@media(max-width:900px){.stagebar{grid-template-columns:1fr}.review-grid{grid-template-columns:1fr 1fr}.campaign-engine{margin:0 -18px;padding:8px 18px}.row{grid-template-columns:1fr auto}.row>span:nth-of-type(2),.row>.danger{display:none}.step-card{flex-wrap:wrap}.step-actions{width:100%}.foundation-note{flex-direction:column}}
</style>
